th$bound <- ifelse(abs(th$value - th$lower) < 0.01, "at lower bound",
                   ifelse(abs(th$value - th$upper) < 0.01, "at upper bound", ""))
th$meaning <- meaning
th |>
  select(Parameter = parameter, Meaning = meaning, Value = value, Lower = lower, Upper = upper, Note = bound) |>
